  type: 'object',
  properties: {
    order_id: { type: 'string' },
    include_history: { type: 'boolean', default: false },
  },
  required: ['order_id'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: TOOL_NAME,
      description:
        'Get the current status of an order by id. Optionally include the chronological status history.',
      inputSchema: SCHEMA,
    },
  ];
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }

  const allowed = ['order_id', 'include_history'];
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      throw new Error(`Invalid field: ${key}`);
    }
  }

  const { order_id, include_history = false } = args;

  if (typeof order_id !== 'string') {
    throw new Error('order_id is required and must be a string');
  }
  if (typeof include_history !== 'boolean') {
    throw new Error('include_history must be a boolean');
  }

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  let text = `Order ${order_id} status: ${order.status}`;
  if (include_history) {
    const history = Array.isArray(order.history) ? [...order.history] : [];
    text += `\nHistory: ${history.join(', ')}`;
  }

  return {
    content: [{ type: 'text', text }],
  };
